const sites={academy57:{place:'prefecture',name:'府学传习院',text:'公开传习筑基功法，备有演武傀。无需加入门派或领取委托。'},guild57:{place:'prefecture',name:'府域会馆',text:'商会公开收货、护路告示与本人委托账。公款按月结算，已交付不重复领款。'},wharf57:{place:'riverTown',name:'渡口灵材栈',text:'水路商队出售凝露芦；到河滩可以自行采集。'},kiln57:{place:'spiritMarket',name:'地火合炉',text:'按公开工艺租用炉位、炼药和制器；炉费已含本次租用。'},vein57:{place:'spiritMarket',name:'坊外矿坡',text:'采集青髓矿需要七日，途中事件会打断。'},reedbed57:{place:'riverTown',name:'渡外芦滩',text:'采凝露芦需要七日。采集不自动增加修为。'}};
const items={thunderPaper57:['惊雷符',44,'符箓','地火合炉绘制；消耗一张造成雷击并打断蓄势'],guardDisk57:['凝罡阵盘',66,'阵具','战中消耗阵盘布置三次阵力的临时防护阵；离场不返还'],riverReed57:['凝露芦',8,'材料','渡口灵材栈或渡外芦滩'],blueOre57:['青髓矿',12,'材料','坊外矿坡或地火合炉'],beastCore57:['凝息妖核',24,'材料','筑基妖兽实战获胜或地火合炉'],yuanPill57:['还元丹',38,'丹药','地火合炉炼制；恢复40真元'],veinSalve57:['温脉膏',42,'丹药','地火合炉炼制；恢复80气血并减轻一年长期伤势'],blade57:['青髓灵刃',160,'法器','地火合炉制成；装备后攻击+8'],armor57:['凝纹法衣',170,'法衣','地火合炉制成；装备后防御+7']};
for(const[id,[name,price,kind,source]]of Object.entries(items)){BAG_ITEMS[id]={name,price,desc:source};C.catalog[id]={id,name,price,kind,grade:'二阶·筑基',currency:'stone',source,desc:source,...(kind==='法器'?{slot:'weapon'}:kind==='法衣'?{slot:'armor'}:{})};}
const recipes={thunderPaper57:{stage:2,days:8,fee:7,materials:{blankPaper52:2,spiritInk52:2,beastCore57:1}},guardDisk57:{stage:3,days:12,fee:12,materials:{arrayStone52:3,blueOre57:2,beastCore57:1}},yuanPill57:{stage:1,days:7,fee:6,materials:{riverReed57:2,herb:3}},veinSalve57:{stage:1,days:7,fee:6,materials:{riverReed57:2,herb:4}},blade57:{stage:2,days:18,fee:20,materials:{blueOre57:4,beastCore57:1,spiritTimber47:2}},armor57:{stage:2,days:18,fee:20,materials:{blueOre57:3,beastCore57:1,riverReed57:3}}};
const paths={};
const rows=[['edge','玄锋凝罡诀','凝罡剑势','burst','edge',{absorb:.09,bt:.006,life:0},{pierce:4},'swordLate52'],['body','金肌养脉功','震岳崩劲','burst','body',{absorb:.06,bt:0,life:6},{hp:30,defense:3},'palmLate52'],['spirit','百转御灵诀','回光御器','steady','spirit',{absorb:.08,bt:.008,life:0},{mp:14},'controlLate52'],['element','澄元归一篇','玄水重浪','steady','element',{absorb:.09,bt:.004,life:0},{mp:8},'element_water252'],['talisman','符枢凝真篇','符光护身','steady','talisman',{absorb:.06,bt:.004,life:0},{mp:8},'ward'],['array','阵脉承真诀','阵前镇身','steady','array',{absorb:.06,bt:.004,life:0},{defense:3},'ward'],['pet','灵契同源经','护生掌','slow','pet',{absorb:.05,bt:0,life:6},{hp:24},'palmLate52'],['puppet','玄枢分神篇','机枢御器','steady','puppet',{absorb:.05,bt:.006,life:0},{mp:12},'controlLate52'],['alchemy','丹息养真经','养脉护身','slow','alchemy',{absorb:.055,bt:0,life:6},{hp:18},'ward'],['forge','地火凝纹篇','锻焰术','burst','forge',{absorb:.065,bt:.004,life:0},{defense:2},'element_fire252']];
for(const [route,mind,art,flow,bonus,effect,battle,baseMove]of rows){const move='foundation_'+route+'57',source=XTQi52Data.moves[baseMove];if(source){XTQi52Data.moves[move]={...source,label:art,cost:(source.cost||0)+2,damage:source.damage+12,desc:'筑基进阶：'+source.desc};Q.moveDefs[move]=XTQi52Data.moves[move];}else Q.moveDefs[move]={label:art,cost:5,desc:'筑基护身，本回合防护增加24'};paths[route]={mind,art};for(const [title,kind]of[[mind,'心法'],[art,'术法']]){const id=route+(kind==='心法'?'Mind57':'Art57'),m={id,kind,tier:'玄',realm57:1,flow,focus:bonus,bonus,price:kind==='心法'?60:32,effect:kind==='心法'?effect:{route:'攻'},battle:kind==='心法'?battle:{},move:kind==='术法'?move:undefined,desc:kind==='心法'?`筑基${XTQi52Data.routes[route].name}心法；${bonus==='body'?'气血与防护':bonus==='spirit'?'真元与分念':'延续本路配功'}。符、阵、灵兽与傀儡仍须实物及照料。`:`筑基篇章，沿用${Q.moveDefs[move]?.label||art}机制；可与其他方向混搭。`};Q.library[title]=m;MANUALS[title]={kind,tier:'玄',from:'府学传习院公开抄本',desc:m.desc,effect:m.effect};BAG_ITEMS[id]={name:'《'+title+'》抄本',price:m.price,desc:m.desc};C.catalog[id]={id,name:BAG_ITEMS[id].name,price:m.price,currency:'stone',kind:'书册',grade:'玄阶·筑基',source:'府学传习院',desc:m.desc};C.manuals[title]={id,name:title,kind,grade:'玄阶',source:'府学传习院',effect:m.effect};}}
Object.assign(Q.enemies,{marsh57:{realm:1,name:'凝露泽蟒',layer:1,hp:160,attack:21,defense:3,intents:['扑咬','蓄势','重扑']},shell57:{realm:1,name:'青甲山魈',layer:2,hp:215,attack:27,defense:6,intents:['重扑','蓄势','扑咬']},hawk57:{realm:1,name:'裂风隼',layer:3,hp:260,attack:32,defense:4,intents:['蓄势','重扑','扑咬']},warden57:{realm:1,name:'石窟獠王',layer:4,hp:310,attack:37,defense:8,intents:['蓄势','重扑','重扑','扑咬']}});
for(const id of ['prefect','ferry','sunset'])if(S.actors[id]?.stock)for(const item of Object.keys(items))S.actors[id].stock[item]=0;
const orders={reed:{title:'府城丹坊备料',item:'riverReed57',qty:2,reward:34},ore:{title:'府城器坊备料',item:'blueOre57',qty:2,reward:46},pill:{title:'府城修士还元丹订货',item:'yuanPill57',qty:1,reward:48},patrol:{title:'府外泽蟒护路',target:'marsh57',need:2,reward:65}};
function peek(){return G?.foundation57?.ownerId===G?.world36?.playerId?G.foundation57:null;}
function state(){if(!peek())G.foundation57={version:1,ownerId:G.world36.playerId,markets:{},order:null,history:[],wins:{},crafted:{}};return G.foundation57;}
const here=id=>G.place===sites[id]?.place&&S.state().room===id;
const trainingHere=()=>here('academy57');
function days(n,act){const r=advanceDays(n,{act,rate:0,incomeMul:0},{stopOnEvent:true});if(r.died){die('寿元耗尽');return false;}if(r.event){startEvent(r.event);return false;}return r.days===n&&G.mode==='idle';}
function transact(fn){const ok=C.atomic(fn);if(!ok)message=C.takeFailure()||'保存失败，钱物与日期已撤回。';render();return ok;}
const month=()=>Math.floor(S.now()/30),marketKey=()=>G.place+'_'+month();
const supply={riverReed57:{site:'wharf57',stock:24},blueOre57:{site:'kiln57',stock:16},beastCore57:{site:'kiln57',stock:6}};
function stock(id){return peek()?.markets[marketKey()]?.stock[id]??supply[id]?.stock??0;}
function note(text){const d=state();d.history.unshift({day:S.now(),text});d.history=d.history.slice(0,30);addLog(text,'mute');}
function dispatch(type,arg=''){
 message='';if(!systemReady())return false;
 if(type==='open'){V.tab='foundation57';render();return true;}
 if(type==='scene'){S.go('scene');return true;}
 if(type==='break'){openBreak();return true;}
 if(type==='book'){const m=Q.library[arg];if(!here('academy57')||G.realm<1||m?.realm57!==1||S.state().books[arg]||G.inventory[m.id]>0||G.stones<m.price)return false;return transact(()=>{stoneChange(G,-m.price,'筑基传习抄本');G.inventory[m.id]=(G.inventory[m.id]||0)+1;note('取得《'+arg+'》抄本，阅读收录后研习。');});}
 if(type==='buy'){const x=supply[arg],price=items[arg]?.[1];if(!x||!here(x.site)||!stock(arg)||G.stones<price)return false;return transact(()=>{const d=state(),m=d.markets[marketKey()]||={stock:{},spent:0,paid:0};m.stock[arg]=stock(arg)-1;stoneChange(G,-price,'府域材料采购');m.spent+=price;G.inventory[arg]=(G.inventory[arg]||0)+1;});}
 if(type==='gather'){const site=arg==='riverReed57'?'reedbed57':arg==='blueOre57'?'vein57':null;if(!site||!here(site)||G.realm<1)return false;return transact(()=>{if(days(7,'府域采材')){G.inventory[arg]=(G.inventory[arg]||0)+1;note('采得'+items[arg][0]+'一份，耗七日。');}});}
 if(type==='craft'){const r=recipes[arg];if(!r||!here('kiln57')||G.realm<1||G.realm===1&&G.layer<r.stage||G.stones<r.fee||Object.entries(r.materials).some(([id,n])=>(G.inventory[id]||0)<n))return false;return transact(()=>{if(!days(r.days,'筑基公开工艺'))return;if(Object.entries(r.materials).some(([id,n])=>(G.inventory[id]||0)<n)||G.stones<r.fee)return;stoneChange(G,-r.fee,'地火炉位与工料');for(const[id,n]of Object.entries(r.materials))G.inventory[id]-=n;G.inventory[arg]=(G.inventory[arg]||0)+1;state().crafted[arg]=(state().crafted[arg]||0)+1;note('按公开标准工艺制成'+items[arg][0]+'一件；不涉及自创丹方或高阶随机炼制。');});}
 if(type==='refit'||type==='nurture'){const key=type==='refit'?'puppet':'pet',comp=G.qi52?.[key],mat=type==='refit'?'blueOre57':'riverReed57';if(!here('kiln57')||G.realm<1||G.realm===1&&G.layer<2||!comp||comp.foundation57||G.stones<18||(G.inventory[mat]||0)<2||(G.inventory.beastCore57||0)<1)return false;return transact(()=>{if(!days(14,'筑基协同温养'))return;const d=G.qi52?.[key];if(!d||d.foundation57||(G.inventory[mat]||0)<2||(G.inventory.beastCore57||0)<1||G.stones<18)return;G.inventory[mat]-=2;G.inventory.beastCore57--;stoneChange(G,-18,'筑基协同温养');d.foundation57=true;note(key==='pet'?'以真实灵材温养已有灵兽，协同伤害增加12；仍须喂养、照料与训练。':'以真实灵材改装已有傀儡，协同伤害增加12；仍消耗灵石和耐久。');});}
 if(type==='use'){if(!['yuanPill57','veinSalve57'].includes(arg)||!(G.inventory[arg]>0))return false;const stats=Q.stats(),saved=G.qi51?.health,h={...stats,hp:Math.min(stats.maxHp,saved?.hp??stats.maxHp),mp:Math.min(stats.maxMp,saved?.mp??stats.maxMp)},mp=arg==='yuanPill57';if(mp?h.mp>=h.maxMp:h.hp>=h.maxHp&&!(G.injured>0))return false;return transact(()=>{Q.vitals();G.inventory[arg]--;if(mp)Q.state().health.mp=Math.min(h.maxMp,h.mp+40);else{Q.state().health.hp=Math.min(h.maxHp,h.hp+80);G.injured=Math.max(0,(G.injured||0)-1);}note('使用'+items[arg][0]+'，按实际状态恢复。');});}
 if(type==='accept'){if(!here('guild57')||G.realm<1||!orders[arg]||peek()?.order)return false;return transact(()=>{state().order={id:arg,progress:0,at:S.now()};note('自愿接下'+orders[arg].title+'；可以取消，无押金和任务锁。');});}
 if(type==='cancel'){if(!peek()?.order)return false;return transact(()=>{note('取消本人府域委托，已有钱物和修行保留。');state().order=null;});}
 if(type==='report'){const o=peek()?.order,r=orders[o?.id];if(!here('guild57')||!r)return false;if(r.target?o.progress<r.need:(G.inventory[r.item]||0)<r.qty)return false;const m=peek()?.markets[marketKey()],budget=300-(m?.paid||0);if(budget<r.reward){message='会馆本月结款预算不足，下月可再来。';render();return false;}return transact(()=>{if(!days(1,'府域交货'))return;if(r.item&&(G.inventory[r.item]||0)<r.qty)return;const d=state(),m=d.markets[marketKey()]||={stock:{},spent:0,paid:0};if(m.paid+r.reward>300)return;if(r.item)G.inventory[r.item]-=r.qty;stoneChange(G,r.reward,'府域委托结款');m.paid+=r.reward;note(r.title+'当面结清，实收'+r.reward+'灵石。');d.order=null;});}
 return false;
}
function augmentStats(s){if(G.realm===1){if(G.equipment?.weapon==='blade57')s.attack+=8;if(G.equipment?.armor==='armor57')s.defense+=7;}return s;}
function finishBattle(b,outcome){if(b.training||outcome!=='win'||!Q.enemies[b.target]?.realm)return;const d=state();d.wins[b.target]=(d.wins[b.target]||0)+1;G.inventory.beastCore57=(G.inventory.beastCore57||0)+1;const o=d.order,r=orders[o?.id];if(r?.target===b.target)o.progress=Math.min(r.need,o.progress+1);b.log.push('取得凝息妖核一份；会馆委托须回府域会馆当面结算。');}
function prep(){return [['本境修为',realmBrim()?'已圆满':'尚待积累'],['现地灵气',currentPlaceQi(G)+'；结丹后的持续修行需达到既有2.0门槛'],['实际伤势',(G.injured||0)+'年'],['可用灵石',G.stones+'；突破投入沿用现有成算'],['失败代价','修为退25%、寿元减3年、受伤3年；可恢复后重试']].map(([k,v])=>esc(k)+'：'+esc(v)).join('<br>');}
function panel(){const d=peek(),o=d?.order,r=orders[o?.id],stats=Q.stats(),health=G.qi51?.health,h={...stats,hp:Math.min(stats.maxHp,health?.hp??stats.maxHp),mp:Math.min(stats.maxMp,health?.mp??stats.maxMp)};let html=card('筑基行程',esc(curRealmTxt())+' · 气血 '+h.hp+'/'+h.maxHp+' · 真元 '+h.mp+'/'+h.maxMp+'<br>初期稳固配功，中期可制进阶器物，后期及圆满面对强敌、积累结丹所需。均可自行安排；不以委托完成度锁修炼。',A('修炼与闭关','q51:cult')+A('功法与配功','q51:arts')+A('既有十路百艺与协同','q51:routes52')+A('安全休养 · 七日','q51:rest')+B('服还元丹','use','yuanPill57',!(G.inventory.yuanPill57>0))+B('用温脉膏','use','veinSalve57',!(G.inventory.veinSalve57>0)));
 html+=card('府域生活去处',Object.entries(sites).map(([id,s])=>esc(placeName(s.place)+' · '+s.name+'：'+s.text)).join('<br>')+'<br>请沿山河地图实际旅行，再在当地街区进入设施。宅院、洞府、雇工、拍卖与既有商户继续正常使用。');
 if(here('academy57'))html+=card('公开传习 · 筑基', '购买抄本 → 行囊阅读 → 功法研习。每部保持自身条目；任选主辅搭配，不永久锁定方向。',Object.entries(paths).map(([id,p])=>'<details class="foundation-path57"><summary>'+esc(XTQi52Data.routes[id].name)+' · '+esc(p.mind)+'</summary><p>'+esc(Q.library[p.mind].desc)+'</p>'+[p.mind,p.art].map(t=>B(t+' · '+Q.library[t].price+'灵石','book',t,!!S.state().books[t]||G.inventory[Q.library[t].id]>0||G.stones<Q.library[t].price||G.realm<1)).join('')+'</details>').join(''))+card('演武场','演练耗一日，不取得战利品或实战委托进度。',A('安全演练 · 一日','q51:train'));
 if(here('wharf57')||here('kiln57'))html+=card('当月材料现货', '按月补货，买入不自动触发任务；可用普通交易处理本人货物。',Object.entries(supply).filter(([,x])=>here(x.site)).map(([id])=>B(items[id][0]+' · '+items[id][1]+'灵石 · 余'+stock(id),'buy',id,!stock(id)||G.stones<items[id][1])).join(''));
 if(here('reedbed57')||here('vein57'))html+=card('实地采材','耗七日取得一份；途中事件或寿尽中止。',B('采一份 · 七日','gather',here('reedbed57')?'riverReed57':'blueOre57',G.realm<1));
 if(here('kiln57'))html+=Object.entries(recipes).map(([id,x])=>card(items[id][0],Object.entries(x.materials).map(([k,n])=>esc(BAG_ITEMS[k].name)+'×'+n).join('、')+'<br>炉费 '+x.fee+'灵石 · '+x.days+'日 · '+(x.stage===2?'筑基中期起':'筑基起')+' · 标准工艺按实物成品结算。',B('租炉制作','craft',id,G.realm<1||G.realm===1&&G.layer<x.stage||G.stones<x.fee||Object.entries(x.materials).some(([k,n])=>(G.inventory[k]||0)<n)))).join('');
 if(here('kiln57'))html+=card('筑基协同温养','筑基中期起，已有灵兽或傀儡可各温养一次。耗对应材料两份、凝息妖核一份、18灵石与14日，协同伤害增加12；照料、喂养、驱动和修复继续按原规则。',B('温养已有灵兽 · 凝露芦×2','nurture','',!G.qi52?.pet||!!G.qi52.pet.foundation57)+B('改装已有傀儡 · 青髓矿×2','refit','',!G.qi52?.puppet||!!G.qi52.puppet.foundation57));
 html+=card('本人府域委托',r?esc(r.title)+'<br>'+(r.target?'胜利 '+o.progress+'/'+r.need:'本人行囊 '+(G.inventory[r.item]||0)+'/'+r.qty+' '+esc(items[r.item][0]))+' · 结款 '+r.reward+'灵石':'当前未接，可在府域会馆自愿选择收货或护路。',r?B('当面交付 · 一日','report','',!here('guild57'))+B('取消委托','cancel'):here('guild57')?Object.entries(orders).map(([id,r])=>B(r.title+' · '+r.reward+'灵石','accept',id,G.realm<1)).join(''):'');
 if(placeHas(PLACES[G.place],'hunt')&&S.state().room==='hunt')html+=card('筑基实战','搜寻耗七日；可挑战更强敌人，失败增加长期伤势；可调息、用药和撤退。战中不能换功、旅行或交货。',Object.entries(Q.enemies).filter(([,e])=>e.realm===1).map(([id,e])=>A(e.name+' · 筑基'+['初','中','后','圆满'][e.layer-1],'q51:hunt',id)).join(''));
 html+=card('结丹准备',prep(),B('查看现有突破方案','break','',!canBreak()))+card('近期往来',d?.history.length?d.history.slice(0,8).map(x=>esc(x.text)).join('<br>'):'暂无本人府域记录。')+B('返回当前场景','scene');return html;
}
function bind(root){root?.querySelectorAll('[data-sb]').forEach(b=>b.onclick=()=>S.dispatch(b.dataset.sb,b.dataset.arg));}
function page(){document.body.classList.add('sb-screen');const scene=document.getElementById('scene');scene.innerHTML='<section class="sb-shell foundation57"><header class="sb-head"><div><small>'+esc(W.locationLabel())+'</small><h2>筑基与府域生活</h2></div></header><div class="sb-scroll">'+(message?'<p role="status">'+esc(message)+'</p>':'')+panel()+'</div></section>';bind(scene);}
XTMap45.rooms=function(base){return [...old.rooms(base),...Object.entries(sites).filter(([,s])=>s.place===G.place).map(([id,s])=>[id,s.name])];};
S.dispatch=function(a,arg){if(a?.startsWith('f57:'))return dispatch(a.slice(4),arg);if(a==='use'&&['yuanPill57','veinSalve57'].includes(arg))return dispatch('use',arg);if(G?.realm===1&&['q51:hub','q51:shop'].includes(a))return dispatch('open');return old.dispatch(a,arg);};
W.renderView=function(){if(G?.mode==='idle'&&!G.qi51?.battle&&(V.tab==='foundation57'||G.realm===1&&V.tab==='hub51')){page();return true;}return old.view();};
renderScene=function(...args){const out=old.scene(...args);if(!G?.root||G.mode!=='idle'||G.qi51?.battle)return out;if(V.tab==='scene'||V.tab==='cult'&&V.sub!=='arts'){const scene=document.getElementById('scene'),host=scene.querySelector('.sb-scroll');if(host&&!host.querySelector('.foundation-entry57')){const div=document.createElement('div');div.className='foundation-entry57';div.innerHTML=card(G.realm===1?'筑基行程':'府域生活',sites[S.state().room]?.text||'传习、制造、护路、商会交货与结丹准备，可分别安排。',B('查看筑基与府域生活','open'));host.append(div);bind(div);}}return out;};
restore=function(raw){try{const s=JSON.parse(raw),d=s.foundation57,obj=x=>x&&typeof x==='object'&&!Array.isArray(x),count=x=>Number.isSafeInteger(x)&&x>=0;if(d){if(!obj(d)||d.version!==1||d.ownerId!==s.world36?.playerId||!obj(d.markets)||!obj(d.wins)||!obj(d.crafted)||!Array.isArray(d.history)||d.history.length>30||d.history.some(h=>!obj(h)||!count(h.day)||typeof h.text!=='string')||Object.values(d.wins).some(x=>!count(x))||Object.values(d.crafted).some(x=>!count(x)))throw Error('府域记录无效');for(const m of Object.values(d.markets))if(!obj(m)||!obj(m.stock)||!count(m.paid)||m.paid>300||!count(m.spent)||Object.entries(m.stock).some(([id,n])=>!supply[id]||!count(n)||n>supply[id].stock))throw Error('府域库存无效');if(d.order&&(!orders[d.order.id]||!count(d.order.progress)||d.order.progress>(orders[d.order.id].need||0)||!count(d.order.at)))throw Error('委托无效');}}catch(e){XTEconomy40.lastRestoreError='筑基府域记录无效，原档保留。';return false;}return old.restore(raw);};
const acquire=XTQi52.acquireReason,study=XTQi52.studyReason;XTQi52.acquireReason=function(t,...a){if(Q.library[t]?.realm57&&G.realm<1)return '筑基后才能传习此篇；已有炼气功法可继续运用。';return acquire(t,...a);};XTQi52.studyReason=function(t,...a){if(Q.library[t]?.realm57&&G.realm<1)return '此篇需要筑基修为。';return study(t,...a);};
const extra=XTQi52.extraMoves,can=XTQi52.canMove,resolve=XTQi52.resolveMove;
for(const[id,label]of[['thunderPaper57','用惊雷符'],['guardDisk57','布凝罡阵'],['pulse57','催动凝罡阵'],['yuanPill57','服还元丹'],['veinSalve57','用温脉膏']])Q.moveDefs[id]={label,cost:0,desc:items[id]?.[3]||'消耗一次阵力，护身24并反击；共三次'};
XTQi52.extraMoves=function(b){return [...extra(b),...['yuanPill57','veinSalve57','thunderPaper57','guardDisk57'].filter(id=>G.inventory[id]>0),...(b.features52?.guard57>0?['pulse57']:[])];};
XTQi52.canMove=function(b,m){if(['yuanPill57','veinSalve57','thunderPaper57','guardDisk57'].includes(m))return G.inventory[m]>0;if(m==='pulse57')return b.features52?.guard57>0;if(m.startsWith('foundation_')&&!XTQi52Data.moves[m])return b.stats.spells.some(t=>Q.moveFor(t)===m);if((m==='sword'||XTQi52Data.moves[m]?.weapon)&&b.stats.weapon==='blade57')return b.stats.spells.some(t=>Q.moveFor(t)===m);return can(b,m);};
XTQi52.resolveMove=function(b,m,act){if(b.features52){b.features52.petCommand=false;b.features52.puppetCommand=false;}b.pierce52=b.stats.pierce52||0;if(m==='thunderPaper57'){G.inventory[m]--;b.charged=false;return {damage:42+Math.floor((b.stats.features52?.talisman||0)*6),skip:act==='蓄势'};}if(m==='guardDisk57'){G.inventory[m]--;b.features52.guard57=3;return {damage:0,guard:24};}if(m==='pulse57'){b.features52.guard57--;return {damage:12+Math.floor((b.stats.features52?.array||0)*5),guard:24};}if(m==='yuanPill57'||m==='veinSalve57'){G.inventory[m]--;if(m==='yuanPill57')b.mp=Math.min(b.stats.maxMp,b.mp+40);else {b.hp=Math.min(b.stats.maxHp,b.hp+80);G.injured=Math.max(0,(G.injured||0)-1);}return {damage:0};}if(m.startsWith('foundation_')&&!XTQi52Data.moves[m])return {damage:0,guard:24};const result=resolve(b,m,act);if(result&&((m==='pet52'&&b.features52.pet?.foundation57)||(m==='puppet52'&&b.features52.puppet?.foundation57)))result.damage=(result.damage||0)+12;return result;};
window.XTFoundation57={paths,sites,recipes,orders,state:peek,dispatch,augmentStats,finishBattle,trainingHere,panel,prep};
